export function eulerBasis(x,y,z){const ry=Math.asin(clamp(z[0],-1,1));return Math.abs(z[0])<.9999999?[Math.atan2(-z[1],z[2]),ry,Math.atan2(-y[0],x[0])]:[Math.atan2(y[2],y[1]),ry,0];}
export function xPose(a,b){const x=unit(sub(b,a)),helper=Math.abs(x[2])>.9?[0,1,0]:[0,0,1],y=unit(cross(helper,x)),z=cross(x,y);return {position:mul(add(a,b),.5),rotation:eulerBasis(x,y,z)};}
export const spinZ=(position,angle)=>({position,rotation:[0,0,angle]});
export const box=(size,position=[0,0,0],color=C.blue)=>({kind:'box',size,position,color});
export const cylinder=(radius,length,position=[0,0,0],color=C.steel,rotation=[0,0,0])=>({kind:'cylinder',radius,length,position,color,rotation});
export const ring=(outer,inner,length,position=[0,0,0],color=C.steel)=>({kind:'ring',outer,inner,length,position,color});
export const rod=(from,to,radius=3,color=C.steel)=>({kind:'rod',from,to,radius,color});
export const sphere=(radius,position=[0,0,0],color=C.gold)=>({kind:'sphere',radius,position,color});
export const part=(id,name,shapes,position=[0,0,0],category='transmission',description=name)=>({id,name,description,category,position,shapes});
export const field=(key,label,unit,value,min,max,step=1)=>({key,label,unit,value,min,max,step});
export const choice=(key,label,value,options)=>({key,label,value,options});
export function define(m){const extra=m.validate;m.validate=p=>{for(const f of m.fields){const v=p[f.key];if(f.options){if(!f.options.some(([k])=>k===v))throw Error(f.label+'选项无效');}else{if(!Number.isFinite(v)||v<f.min||v>f.max)throw Error(f.label+'超出范围');if(f.integer&&!Number.isInteger(v))throw Error(f.label+'须为整数');}}if(!Number.isFinite(p.inputRPM)||p.inputRPM<0)throw Error('转速无效');extra?.(p);};return m;}
export const metric=(label,value,unit='')=>({label,value,unit});
export function circleIntersection(a,ra,b,rb,sign=1){const d=length(sub(b,a));if(d>ra+rb+1e-7||d<Math.abs(ra-rb)-1e-7||d<1e-9)throw Error('当前杆长无法闭合');const u=mul(sub(b,a),1/d),along=(ra*ra-rb*rb+d*d)/(2*d),h=Math.sqrt(Math.max(0,ra*ra-along*along));return [a[0]+along*u[0]-sign*h*u[1],a[1]+along*u[1]+sign*h*u[0],a[2]||0];}
export const circle=(r,n=64)=>Array.from({length:n},(_,i)=>[r*Math.cos(i*TAU/n),r*Math.sin(i*TAU/n)]);
export function sector(inner,outer,a,b,n=24){return [...Array.from({length:n+1},(_,i)=>{const t=a+(b-a)*i/n;return [outer*Math.cos(t),outer*Math.sin(t)];}),...Array.from({length:n+1},(_,i)=>{const t=b-(b-a)*i/n;return [inner*Math.cos(t),inner*Math.sin(t)];})];}
export function sprocket(teeth,pitch=12.7,width=4,color=C.steel,bore=null){const R=teeth*pitch/TAU,inner=bore??Math.max(3,R*.18),profile=[[0,-.32],[.15,-.29],[.28,-.08],[.4,.11],[.6,.11],[.72,-.08],[.85,-.29],[1,-.32]],points=[];for(let i=0;i<teeth;i++)for(const [f,h] of profile){const a=(i+f)*TAU/teeth,r=R+h*pitch;points.push([r*Math.cos(a),r*Math.sin(a)]);}return [{kind:'polygon',points,holes:[circle(inner,48)],depth:width,color},ring(R*.4,inner,width+2,[0,0,0],color),box([R*.45,1,width+.5],[R*.62,0,0],C.gold)];}
export function linkShapes(pitch=12.7,width=5){return [box([pitch,3.5,1],[0,0,-width/2],C.steel),box([pitch,3.5,1],[0,0,width/2],C.steel),cylinder(pitch*.22,width-1,[-pitch/2,0,0],C.gold)];}
export function grouped(p,group,first=false){p.assemblyGroup=group;p.hiddenInList=!first;return p;}
export function linkPose(path,s,pitch){const a=path.sample(s).position,b=path.sample(s+pitch).position,p=xPose(a,b);p.scale=[length(sub(b,a))/pitch,1,1];return p;}
export function polylinePath(points,closed=false){const pts=closed?[...points,points[0]]:points,lens=[0];for(let i=1;i<pts.length;i++)lens.push(lens.at(-1)+length(sub(pts[i],pts[i-1])));const total=lens.at(-1);return {length:total,sample(s){s=mod(s,total);let i=1;while(lens[i]<s)i++;const t=(s-lens[i-1])/(lens[i]-lens[i-1]);return {position:add(pts[i-1],mul(sub(pts[i],pts[i-1]),t)),tangent:unit(sub(pts[i],pts[i-1])),segment:i-1};}};}
// Exact planar circle tangencies, plus explicitly linear lateral chain spans.
// dir=-1 clockwise; dir=+1 counterclockwise, needed for derailleur S-routing.
export function circleRoute(circles){const edges=circles.map((c,i)=>{const n=circles[(i+1)%circles.length],dx=n.center[0]-c.center[0],dy=n.center[1]-c.center[1],D=Math.hypot(dx,dy),q=-c.dir*c.radius+n.dir*n.radius;if(Math.abs(q)>=D)throw Error('链轮与导轮间距不足');const a=Math.atan2(dy,dx)+Math.acos(q/D),N=[Math.cos(a),Math.sin(a)];return {a:[c.center[0]-c.dir*c.radius*N[0],c.center[1]-c.dir*c.radius*N[1],c.center[2]||0],b:[n.center[0]-n.dir*n.radius*N[0],n.center[1]-n.dir*n.radius*N[1],n.center[2]||0]};});
  const sections=[];let total=0;
  for(let i=0;i<circles.length;i++){const c=circles[i],prev=edges[mod(i-1,circles.length)],out=edges[i],a=Math.atan2(prev.b[1]-c.center[1],prev.b[0]-c.center[0]),b=Math.atan2(out.a[1]-c.center[1],out.a[0]-c.center[0]),sweep=mod(c.dir*(b-a),TAU),arc=c.radius*sweep;sections.push({start:total,length:arc,type:'arc',circle:c,a,sweep,index:i});total+=arc;const len=length(sub(out.b,out.a));sections.push({start:total,length:len,type:'line',...out,index:i});total+=len;}
  return {length:total,sections,edges,sample(s){s=mod(s,total);const seg=sections.find(x=>s<x.start+x.length)||sections.at(-1),t=(s-seg.start)/seg.length;if(seg.type==='line')return {position:add(seg.a,mul(sub(seg.b,seg.a),t)),tangent:unit(sub(seg.b,seg.a)),segment:'line'+seg.index};const {circle:c}=seg,a=seg.a+c.dir*seg.sweep*t;return {position:[c.center[0]+c.radius*Math.cos(a),c.center[1]+c.radius*Math.sin(a),c.center[2]||0],tangent:[-c.dir*Math.sin(a),c.dir*Math.cos(a),0],segment:'arc'+seg.index};}};
}
const memoStore=new Map();
export function memo(name,p,fn){const key=name+JSON.stringify(p);if(!memoStore.has(key)){if(memoStore.size>100)memoStore.clear();memoStore.set(key,fn());}return memoStore.get(key);}
export function radialMesh(start,end,radial,nx,na=72,{inner=false,outer=0,half=false}={}){const vertices=[],indices=[],theta0=half?Math.PI:0,span=half?Math.PI:TAU;for(let x=0;x<=nx;x++)for(let a=0;a<=na;a++){const X=start+(end-start)*x/nx,t=theta0+span*a/na,r=radial(X,t);vertices.push(X,r*Math.cos(t),r*Math.sin(t));}const idx=(x,a)=>x*(na+1)+a;for(let x=0;x<nx;x++)for(let a=0;a<na;a++){const A=idx(x,a),B=idx(x,a+1),C1=idx(x+1,a+1),D=idx(x+1,a);indices.push(...(inner?[A,C1,B,A,D,C1]:[A,B,C1,A,C1,D]));}for(const x of [0,nx]){const X=x?end:start;for(let a=0;a<na;a++){const A=idx(x,a),B=idx(x,a+1);if(inner){const ta=theta0+span*a/na,tb=theta0+span*(a+1)/na,C1=vertices.length/3;vertices.push(X,outer*Math.cos(ta),outer*Math.sin(ta),X,outer*Math.cos(tb),outer*Math.sin(tb));indices.push(A,B,C1+1,A,C1+1,C1);}else{const C1=vertices.length/3;vertices.push(X,0,0);indices.push(...(x?[C1,A,B]:[C1,B,A]));}}}if(inner){const base=vertices.length/3;for(const X of [start,end])for(let a=0;a<=na;a++){const t=theta0+span*a/na;vertices.push(X,outer*Math.cos(t),outer*Math.sin(t));}for(let a=0;a<na;a++)indices.push(base+a,base+a+1,base+na+2+a,base+a,base+na+2+a,base+na+1+a);if(half)for(const a of [0,na])for(let x=0;x<nx;x++){const A=idx(x,a),B=idx(x+1,a),C1=vertices.length/3,t=theta0+span*a/na;vertices.push(start+(end-start)*x/nx,outer*Math.cos(t),outer*Math.sin(t),start+(end-start)*(x+1)/nx,outer*Math.cos(t),outer*Math.sin(t));indices.push(A,B,C1+1,A,C1+1,C1);}}return {kind:'mesh',vertices,indices};}
